// Generates lib/theme/tokens.g.dart from design/tokens.json (the design
// system's tokens, copied unchanged) and tool/theme/artboard_colours.json
// (colours the artboards set directly that tokens.json does not carry yet).
//
//   dart run tool/gen_theme.dart
//
// test/theme/tokens_up_to_date_test.dart fails when the generated file is
// stale. Nothing in lib/theme is a hand-picked colour: everything comes from
// these two files.
import 'dart:convert';
import 'dart:io';

const tokensPath = 'design/tokens.json';
const artboardPath = 'tool/theme/artboard_colours.json';
const outputPath = 'lib/theme/tokens.g.dart';

void main() {
  final out = generateTokens(
    File(tokensPath).readAsStringSync(),
    File(artboardPath).readAsStringSync(),
  );
  File(outputPath).writeAsStringSync(out);
  stdout.writeln('Wrote $outputPath');
}

/// Pure function so the staleness test can run it without touching disk.
String generateTokens(String tokensJson, String artboardJson) {
  final tokens = jsonDecode(tokensJson) as Map<String, dynamic>;
  final artboard = jsonDecode(artboardJson) as Map<String, dynamic>;
  final colour = (tokens['color'] as Map<String, dynamic>)['tokens'] as List;
  final themes = [
    for (final t in (tokens['color'] as Map<String, dynamic>)['themes'] as List)
      (t as Map<String, dynamic>)['id'] as String,
  ];
  if (themes.join(',') != 'light,dark') {
    throw FormatException('Expected themes light and dark, got $themes');
  }

  final byName = <String, Object>{
    for (final t in colour)
      (t as Map<String, dynamic>)['name'] as String: t['value'] as Object,
  };
  final usage = <String, String>{
    for (final t in colour)
      (t as Map<String, dynamic>)['name'] as String:
          (t['usage'] ?? '') as String,
  };

  String resolve(
    Object value,
    String theme,
    Map<String, Object> scope, [
    int depth = 0,
  ]) {
    if (depth > 8) throw FormatException('Reference loop at $value');
    if (value is Map) {
      return resolve(value[theme] as Object, theme, scope, depth + 1);
    }
    final s = value as String;
    if (s.startsWith('{') && s.endsWith('}')) {
      final ref = s.substring(1, s.length - 1);
      final target = scope[ref] ?? byName[ref];
      if (target == null) throw FormatException('Unknown token {$ref}');
      return resolve(target, theme, scope, depth + 1);
    }
    if (!RegExp(r'^#[0-9a-fA-F]{6}$').hasMatch(s)) {
      throw FormatException('Not a #rrggbb colour: $s');
    }
    return s.toLowerCase();
  }

  final b = StringBuffer()
    ..writeln('// GENERATED by tool/gen_theme.dart from $tokensPath and')
    ..writeln(
      '// $artboardPath. Do not edit; run `dart run tool/gen_theme.dart`.',
    )
    ..writeln('// ignore_for_file: constant_identifier_names')
    ..writeln()
    ..writeln("import 'package:flutter/material.dart';")
    ..writeln();

  // Raw palette (theme-independent values only).
  b
    ..writeln('/// Fixed palette tokens: the same in both themes.')
    ..writeln('abstract final class VpPalette {');
  for (final t in colour) {
    final m = t as Map<String, dynamic>;
    if (m['value'] is String && !(m['value'] as String).startsWith('{')) {
      b
        ..writeln('  /// ${_oneLine(usage[m['name']]!)}')
        ..writeln(
          '  static const ${_camel(m['name'] as String)} = '
          '${_colour(m['value'] as String)};',
        );
    }
  }
  b
    ..writeln('}')
    ..writeln();

  // Themed colour set as a ThemeExtension.
  final names = [
    for (final t in colour) (t as Map<String, dynamic>)['name'] as String,
  ];
  final shadows = [
    for (final t
        in (tokens['shadow'] as Map<String, dynamic>)['tokens'] as List)
      t as Map<String, dynamic>,
  ];
  final fields = [for (final n in names) _camel(n)];
  final shadowFields = [for (final s in shadows) _camel(s['name'] as String)];

  b
    ..writeln(
      '/// Every colour token resolved for one theme, plus the shadows.',
    )
    ..writeln('@immutable')
    ..writeln('class VpColors extends ThemeExtension<VpColors> {')
    ..writeln('  const VpColors({');
  for (final f in [...fields, ...shadowFields]) {
    b.writeln('    required this.$f,');
  }
  b.writeln('  });');
  for (var i = 0; i < names.length; i++) {
    b
      ..writeln()
      ..writeln('  /// ${_oneLine(usage[names[i]]!)}')
      ..writeln('  final Color ${fields[i]};');
  }
  for (var i = 0; i < shadows.length; i++) {
    b
      ..writeln()
      ..writeln('  /// ${_oneLine((shadows[i]['usage'] ?? '') as String)}')
      ..writeln('  final List<BoxShadow> ${shadowFields[i]};');
  }
  b
    ..writeln()
    ..writeln('  @override')
    ..writeln('  VpColors copyWith({');
  for (final f in fields) {
    b.writeln('    Color? $f,');
  }
  for (final f in shadowFields) {
    b.writeln('    List<BoxShadow>? $f,');
  }
  b.writeln('  }) => VpColors(');
  for (final f in [...fields, ...shadowFields]) {
    b.writeln('        $f: $f ?? this.$f,');
  }
  b
    ..writeln('      );')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  VpColors lerp(VpColors? other, double t) {')
    ..writeln('    if (other == null) return this;')
    ..writeln('    return VpColors(');
  for (final f in fields) {
    b.writeln('      $f: Color.lerp($f, other.$f, t)!,');
  }
  for (final f in shadowFields) {
    b.writeln('      $f: BoxShadow.lerpList($f, other.$f, t)!,');
  }
  b
    ..writeln('    );')
    ..writeln('  }')
    ..writeln('}')
    ..writeln();

  for (final theme in themes) {
    b.writeln('const vp${_cap(theme)}Colors = VpColors(');
    for (var i = 0; i < names.length; i++) {
      b.writeln(
        '  ${fields[i]}: ${_colour(resolve(byName[names[i]]!, theme, const {}))},',
      );
    }
    for (var i = 0; i < shadows.length; i++) {
      final v = shadows[i]['value'];
      final css = (v is Map ? v[theme] : v) as String;
      b.writeln('  ${shadowFields[i]}: ${_shadows(css)},');
    }
    b
      ..writeln(');')
      ..writeln();
  }

  // Artboard colours (not in tokens.json yet).
  final extra = [
    for (final t in artboard['tokens'] as List) t as Map<String, dynamic>,
  ];
  b
    ..writeln(
      '/// Colours the artboards set directly that tokens.json does not carry',
    )
    ..writeln('/// (from $artboardPath). Proposed for tokens.json.')
    ..writeln('@immutable')
    ..writeln(
      'class VpArtboardColours extends ThemeExtension<VpArtboardColours> {',
    )
    ..writeln('  const VpArtboardColours({');
  for (final e in extra) {
    b.writeln('    required this.${_camel(e['name'] as String)},');
  }
  b.writeln('  });');
  for (final e in extra) {
    b
      ..writeln()
      ..writeln('  /// ${_oneLine(e['source'] as String)}')
      ..writeln('  final Color ${_camel(e['name'] as String)};');
  }
  b
    ..writeln()
    ..writeln('  @override')
    ..writeln('  VpArtboardColours copyWith({');
  for (final e in extra) {
    b.writeln('    Color? ${_camel(e['name'] as String)},');
  }
  b.writeln('  }) => VpArtboardColours(');
  for (final e in extra) {
    final f = _camel(e['name'] as String);
    b.writeln('        $f: $f ?? this.$f,');
  }
  b
    ..writeln('      );')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  VpArtboardColours lerp(VpArtboardColours? other, double t) {')
    ..writeln('    if (other == null) return this;')
    ..writeln('    return VpArtboardColours(');
  for (final e in extra) {
    final f = _camel(e['name'] as String);
    b.writeln('      $f: Color.lerp($f, other.$f, t)!,');
  }
  b
    ..writeln('    );')
    ..writeln('  }')
    ..writeln('}')
    ..writeln();
  for (final theme in themes) {
    b.writeln('const vp${_cap(theme)}ArtboardColours = VpArtboardColours(');
    for (final e in extra) {
      b.writeln(
        '  ${_camel(e['name'] as String)}: '
        '${_colour(resolve(e['value'] as Object, theme, const {}))},',
      );
    }
    b
      ..writeln(');')
      ..writeln();
  }

  // Spacing, radii, sizes.
  for (final (group, cls, prefix) in [
    ('spacing', 'VpSpace', 'space-'),
    ('radius', 'VpRadius', 'radius-'),
    ('size', 'VpSize', ''),
  ]) {
    final g = tokens[group] as Map<String, dynamic>;
    b
      ..writeln('/// ${_oneLine((g['note'] ?? group) as String)}')
      ..writeln('abstract final class $cls {');
    for (final t in g['tokens'] as List) {
      final m = t as Map<String, dynamic>;
      var n = m['name'] as String;
      if (prefix.isNotEmpty && n.startsWith(prefix)) {
        n = n.substring(prefix.length);
      }
      final id = RegExp(r'^\d').hasMatch(n) ? 's$n' : _camel(n);
      b
        ..writeln('  /// ${_oneLine((m['usage'] ?? '') as String)}')
        ..writeln('  static const double $id = ${_px(m['value'] as String)};');
    }
    b
      ..writeln('}')
      ..writeln();
  }

  // Type scale.
  final type = tokens['type'] as Map<String, dynamic>;
  final families = (type['families'] as Map<String, dynamic>).map(
    (k, v) => MapEntry(k, _families(v as String)),
  );
  b
    ..writeln(
      '/// Font families as tokens.json names them; the first is bundled',
    )
    ..writeln('/// (Unbounded, Manrope) or left to the platform (mono).')
    ..writeln('abstract final class VpFonts {');
  families.forEach((k, v) {
    b.writeln("  static const $k = '${v.first}';");
  });
  b
    ..writeln('}')
    ..writeln()
    ..writeln(
      '/// The type scale. Variable fonts: the weight is set on the wght axis too.',
    )
    ..writeln('abstract final class VpType {');
  for (final g in type['groups'] as List) {
    final gm = g as Map<String, dynamic>;
    final fam = families[gm['family'] as String]!;
    for (final s in gm['styles'] as List) {
      final sm = s as Map<String, dynamic>;
      final size = _px(sm['fontSize'] as String);
      final lh = _px(sm['lineHeight'] as String);
      final w = sm['fontWeight'] as int;
      final ls = sm['letterSpacing'] as String?;
      b
        ..writeln(
          '  /// ${gm['name']}: ${_oneLine((sm['usage'] ?? '') as String)}',
        )
        ..writeln('  static const ${_camel(sm['name'] as String)} = TextStyle(')
        ..writeln("    fontFamily: '${fam.first}',");
      if (fam.length > 1) {
        b.writeln(
          '    fontFamilyFallback: [${fam.skip(1).map((f) => "'$f'").join(', ')}],',
        );
      }
      b
        ..writeln('    fontSize: ${_num(size)},')
        ..writeln('    height: ${_num(lh / size)},')
        ..writeln('    leadingDistribution: TextLeadingDistribution.even,')
        ..writeln('    fontWeight: FontWeight.w$w,')
        ..writeln("    fontVariations: [FontVariation('wght', $w)],");
      if (ls != null) {
        b.writeln('    letterSpacing: ${_num(_em(ls) * size)},');
      }
      b.writeln('  );');
    }
  }
  b.writeln('}');
  return b.toString();
}

String _camel(String kebab) {
  final parts = kebab.split('-');
  return parts.first + parts.skip(1).map(_cap).join();
}

String _cap(String s) => s.isEmpty ? s : s[0].toUpperCase() + s.substring(1);

String _colour(String hex) => 'Color(0xFF${hex.substring(1).toUpperCase()})';

String _oneLine(String s) => s.replaceAll(RegExp(r'\s+'), ' ').trim();

double _px(String v) {
  if (!v.endsWith('px')) throw FormatException('Expected px: $v');
  return double.parse(v.substring(0, v.length - 2));
}

double _em(String v) {
  if (!v.endsWith('em')) throw FormatException('Expected em: $v');
  return double.parse(v.substring(0, v.length - 2));
}

String _num(double v) {
  final r = (v * 10000).roundToDouble() / 10000;
  return r == r.truncateToDouble() ? '${r.toInt()}.0' : '$r';
}

List<String> _families(String css) => [
  for (final f in css.split(','))
    f.trim().replaceAll('"', '').replaceAll("'", ''),
];

String _shadows(String css) {
  if (css.trim() == 'none') return '<BoxShadow>[]';
  final re = RegExp(
    r'(-?[\d.]+)(?:px)?\s+(-?[\d.]+)(?:px)?\s+([\d.]+)(?:px)?\s+rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)',
  );
  final items = <String>[];
  for (final m in re.allMatches(css)) {
    final a = (double.parse(m[7]!) * 255).round();
    final argb =
        (a << 24) |
        (int.parse(m[4]!) << 16) |
        (int.parse(m[5]!) << 8) |
        int.parse(m[6]!);
    items.add(
      'BoxShadow(offset: Offset(${_num(double.parse(m[1]!))}, '
      '${_num(double.parse(m[2]!))}), blurRadius: ${_num(double.parse(m[3]!))}, '
      'color: Color(0x${argb.toRadixString(16).padLeft(8, '0').toUpperCase()}))',
    );
  }
  if (items.isEmpty) throw FormatException('Unparsed shadow: $css');
  return '<BoxShadow>[${items.join(', ')}]';
}
